import java.util.Arrays;
import java.util.Random;
import java.lang.reflect.Method;

public class Harness {
    public static void main(String[] a) throws Exception {
        Method sort = MergeSort.class.getDeclaredMethod("sort", int[].class);
        sort.setAccessible(true);

        // null and empty / single must not throw
        sort.invoke(null, (Object) null);
        sort.invoke(null, (Object) new int[]{});
        sort.invoke(null, (Object) new int[]{42});

        Random rnd = new Random(12345);
        int trials = 5000;
        for (int t = 0; t < trials; t++) {
            int len = rnd.nextInt(60);
            int[] arr = new int[len];
            for (int i = 0; i < len; i++) arr[i] = rnd.nextInt(21) - 10; // dups + negatives
            int[] expected = arr.clone();
            Arrays.sort(expected);
            sort.invoke(null, (Object) arr);
            if (!Arrays.equals(arr, expected)) {
                System.out.println("MISMATCH at trial " + t);
                System.out.println("got=" + Arrays.toString(arr));
                System.out.println("exp=" + Arrays.toString(expected));
                System.exit(1);
            }
        }
        // explicit edge arrays
        int[][] cases = {
            {}, {1}, {2,1}, {1,2}, {5,5,5,5}, {3,-1,-1,3,0}, {9,8,7,6,5,4,3,2,1,0}
        };
        for (int[] c : cases) {
            int[] exp = c.clone(); Arrays.sort(exp);
            int[] got = c.clone(); sort.invoke(null, (Object) got);
            if (!Arrays.equals(got, exp)) { System.out.println("edge MISMATCH " + Arrays.toString(c)); System.exit(1); }
        }
        System.out.println("ALL " + trials + " randomized trials + edge cases PASS");
    }
}
